<script lang="ts">
 import {onMount} from 'svelte';
 import {Button} from '$lib/components/ui/button';
 import * as Select from '$lib/components/ui/select';
 import {Switch} from '$lib/components/ui/switch';
 import MeetingRecordings from '$lib/MeetingRecordings.svelte';
 import MeetingPanel from '$lib/MeetingPanel.svelte';
 import PositionIcon from '$lib/PositionIcon.svelte';
 import HotkeySettings from '$lib/HotkeySettings.svelte';
 import Icon from '$lib/Icon.svelte';import Wave from '$lib/Wave.svelte';import Bubble from '$lib/Bubble.svelte';
 import {studio,connect,act,setting,size} from '$lib/studio.svelte';
 let page=$state('studio');let confirm=$state('');let copied=$state('');let systemDark=$state(true);
 const bubble=new URLSearchParams(location.search).has('bubble');
 let snapshot=$derived(studio.state);let settings=$derived(snapshot.settings);
 let dictating=$derived(['loading','recording','stopping'].includes(snapshot.status)&&!snapshot.fileName);
 let meeting=$derived(snapshot.status.startsWith('meeting'));
 let active=$derived(dictating||meeting);
 let importing=$derived(snapshot.status==='transcribing'||(snapshot.status==='stopping'&&!!snapshot.fileName));
 let selected=$derived(snapshot.models.find(m=>m.id===settings.model));
 let installed=$derived(snapshot.models.filter(m=>m.installed));
 onMount(()=>{let cleanup=()=>{};let disposed=false;connect().then(fn=>{if(disposed)fn();else cleanup=fn;});const media=matchMedia('(prefers-color-scheme: dark)');systemDark=media.matches;const change=()=>systemDark=media.matches;media.addEventListener('change',change);return()=>{disposed=true;cleanup();media.removeEventListener('change',change);};});
 $effect(()=>{document.documentElement.classList.toggle('dark',settings.theme==='dark'||(settings.theme==='system'&&systemDark));document.documentElement.classList.toggle('bubble-window',bubble);});
 async function copy(text:string,id:string){await act('CopyText',text);if(!studio.notice){copied=id;setTimeout(()=>copied='',2000);}}
 const positions=[{id:'top-left',label:'Top left'},{id:'top-center',label:'Top middle'},{id:'top-right',label:'Top right'},{id:'middle-left',label:'Middle left'},{id:'center',label:'Center'},{id:'middle-right',label:'Middle right'},{id:'bottom-left',label:'Bottom left'},{id:'bottom-center',label:'Bottom middle'},{id:'bottom-right',label:'Bottom right'}];
 const titles:Record<string,string>={studio:'THE STUDIO',models:'MODEL GARAGE',history:'REWIND',settings:'MAKE IT YOURS'};
 const descriptions:Record<string,string>={studio:'Less typing. More thinking out loud.',models:'Pick your engine. Keep every word on your machine.',history:'Good thoughts deserve a second copy.',settings:'Your voice. Your rules.'};
</script>
{#snippet choose(kind:'model'|'language')}
 <Select.Root type="single" value={kind==='model'?settings.model:settings.language} onValueChange={v=>{if(v)setting({[kind]:v});}} disabled={active||importing}>
  <Select.Trigger aria-label={kind==='model'?'Recognition model':'Recognition language'}>{kind==='model'?(selected?.name||settings.model):({auto:'Auto detect',en:'English',de:'Deutsch'}[settings.language])}</Select.Trigger>
  <Select.Content>{#if kind==='model'}{#each snapshot.models as m}<Select.Item value={m.id} label={m.name}>{m.name}{!m.installed?' · not downloaded':''}</Select.Item>{/each}{:else}{#each [{id:'auto',label:'Auto detect'},{id:'en',label:'English'},{id:'de',label:'Deutsch'}] as l}<Select.Item value={l.id} label={l.label}>{l.label}</Select.Item>{/each}{/if}</Select.Content>
 </Select.Root>
{/snippet}
{#if bubble}
 <div class="bubble-host"><Bubble/>{#if studio.notice||snapshot.error}<div class="bubble-error" role="alert">{studio.notice||snapshot.error}</div>{/if}</div>
{:else}
 <div class="app-shell">
  <aside class="sidebar">
   <div class="brand"><span class="brand-mark"><img src="/afk-neon.png" alt="" width="56" height="56"/></span><div>AFK<span>AWAY FROM KEYBOARD</span></div></div>
   <div class="sidebar-label">YOUR PRIVATE AIRSPACE</div>
   <nav aria-label="Main navigation">{#each [{id:'studio',label:'Studio',icon:'mic'},{id:'models',label:'Models',icon:'models'},{id:'history',label:'History',icon:'history'},{id:'settings',label:'Settings',icon:'settings'}] as item}<Button variant="ghost" class={`nav-item ${page===item.id?'selected':''}`} onclick={()=>{page=item.id;confirm='';}} aria-current={page===item.id?'page':undefined}><Icon name={item.icon}/><span>{item.label}</span>{#if item.id==='history'}<small>{snapshot.history.length.toString().padStart(2,'0')}</small>{/if}{#if page===item.id}<span class="nav-slash">//</span>{/if}</Button>{/each}</nav>
   <div class="sidebar-bottom"><div class="local-tag"><span class="status-dot"></span>LOCAL FIRST. ALWAYS.</div><p>No account.<br>No subscription.<br>Just your voice.</p><div class="sidebar-actions"><Button variant="outline" disabled={!['recording','meeting'].includes(snapshot.status)} onclick={()=>act('ShowBubble')}><Icon name="bubble"/> Show bubble</Button><Button variant="ghost" onclick={()=>act('Quit')} aria-label="Quit AFK"><Icon name="power"/></Button></div><span class="version">AFK / EXPERIMENT 001</span></div>
  </aside>
  <main>
   <div class="topline"><span>VOICE → TEXT → WHATEVER’S NEXT</span><span class="engine-label"><i></i>{studio.native?'ON-DEVICE ENGINE':'BROWSER PREVIEW'}</span></div>
   <header class="page-heading"><div><div class="eyebrow">{page==='studio'?'01 / OPEN MIC':page==='models'?'02 / UNDER THE HOOD':page==='history'?'03 / THE ARCHIVE':'04 / CONTROL ROOM'}</div><h1>{titles[page]}<span>.</span></h1><p>{descriptions[page]}</p></div><span class="scribble" aria-hidden="true">{page==='studio'?'say it.':page==='models'?'go big.':page==='history'?'again!':'remix.'}</span></header>
   {#if studio.notice||snapshot.error}<div class="notice" role="alert">{studio.notice||snapshot.error}</div>{/if}
   {#if !studio.native}<div class="preview-note">Design preview · Recording, downloads and clipboard run in the desktop app.</div>{/if}
   {#if page==='studio'}
    <div class="studio-modes"><section class="recorder panel" class:mode-selected={settings.mode!=='meeting'}><div class="panel-top"><span><span class="status-dot" class:recording={dictating}></span>{snapshot.status==='recording'?'MIC IS LIVE':snapshot.status==='loading'?'WARMING UP':snapshot.status==='stopping'?'FINISHING UP':importing?'TRANSCRIBING FILE':'READY WHEN YOU ARE'}</span><span class="tag">WHISPER / CUDA</span></div><div class="recorder-center"><Wave active={dictating} large/><h2>{snapshot.status==='recording'?'THINK OUT LOUD.':snapshot.status==='loading'?'ONE MOMENT.':importing?'WORKING ON YOUR FILE.':'DICTATION.'}</h2><p>{importing?'The result will appear here when ready. You can cancel below.':dictating?'Press stop when you’re done. We’ll copy the words.':'Hit record. Speak freely. Your words land on your clipboard.'}</p><Button class={`record-button ${dictating?'is-recording':''}`} onclick={()=>act('ToggleDictation')} disabled={meeting||importing||!studio.ready||snapshot.status==='stopping'||!!snapshot.preparing||(!dictating&&!selected?.installed&&studio.native)}><Icon name={dictating?'stop':'mic'} size={22}/>{importing?'FILE IMPORT IN PROGRESS':dictating?'STOP & COPY':'START DICTATION'}<span>↗</span></Button><Button variant="ghost" class="mode-choice" disabled={active||importing} aria-pressed={settings.mode!=='meeting'} onclick={()=>setting({mode:'dictation'})}>{settings.mode!=='meeting'?'✓ Global shortcut starts dictation':'Use global shortcut for dictation'}</Button><div class="shortcut">{#each settings.hotkey.split('+').filter(Boolean) as key}<kbd>{key}</kbd>{/each}<span>{snapshot.hotkeyActive?'global · any app':'configure global shortcut in Settings'}</span></div></div><div class="record-options"><div><span class="field-label">ENGINE</span>{@render choose('model')}</div><div><span class="field-label">LANGUAGE</span>{@render choose('language')}</div></div></section><MeetingPanel/></div>
    <MeetingRecordings/>
    {#if snapshot.meetingFolder}<p class="meeting-location">Meeting audio &amp; transcript: <span>{snapshot.meetingFolder}</span></p>{/if}
    {#if snapshot.transcript}<section class="transcript panel"><div class="panel-top"><span>{snapshot.status==='meeting-processing'?'PROCESSING MEETING':dictating?'LIVE TRANSCRIPT':'LAST TRANSCRIPT'}</span><Button variant="ghost" onclick={()=>copy(snapshot.transcript,'latest')}><Icon name="copy"/>{copied==='latest'?'Copied':'Copy'}</Button></div><p>{snapshot.transcript}</p></section>{/if}
    <div class="below-grid"><section class="bubble-preview panel"><div class="panel-top"><span>SMALL WINDOW. BIG IDEAS.</span><Icon name="bubble"/></div><div class="bubble-stage"><div class="stage-cross a">+</div><div class="stage-cross b">+</div><Bubble preview/></div><div class="preview-footer"><span>Appears while listening. Click the waveform to expand.</span><Button variant="ghost" disabled={!['recording','meeting'].includes(snapshot.status)} onclick={()=>act('ShowBubble')}>Pop it out <Icon name="arrow"/></Button></div></section><section class="note-card"><span class="tape"></span><Icon name="bolt" size={35}/><h3>OFF THE CLOUD.<br>ON YOUR TERMS.</h3><p>English. Deutsch. A little of both.<br>All four models can detect your language automatically.</p><Button variant="ghost" onclick={()=>page='models'}>Meet your models <Icon name="arrow"/></Button></section></div>
   <section class="file-import panel">
    <div><h2>TRANSCRIBE A FILE</h2><p>{snapshot.fileName ? snapshot.fileName+' · '+snapshot.fileStage : 'Audio files → local transcript. Uses your selected model and language.'}</p><div class="speaker-option"><Switch aria-label="Identify speakers" checked={settings.diarization} disabled={active||importing||!!snapshot.preparing||(!snapshot.diarizationReady&&!settings.diarization)} onCheckedChange={diarization=>setting({diarization})}/><span>Identify speakers · {snapshot.diarizationReady?'Nemotron 3': 'prepare Nemotron in Model Garage'}</span></div></div>
    {#if importing}<Button variant="outline" disabled={snapshot.status==='stopping'} onclick={()=>act('CancelFile')}>{snapshot.status==='stopping'?'CANCELLING…':'CANCEL IMPORT'}</Button>{:else}<Button variant="outline" disabled={active||!!snapshot.preparing||!studio.ready} onclick={()=>act('ChooseFile')}>CHOOSE FILE</Button>{/if}
   </section>
   {:else if page==='models'}
    <section class="nemotron-card panel"><div><span class="tag">OPTIONAL · SPEAKER LABELS</span><h2>NEMOTRON 3</h2><p>Who spoke when. Up to 8 speakers · 107 MB Q8 model.<br>Labels remote speakers when processing recorded meetings.<br>Also available as an optional step for file imports.</p></div><div class="model-actions">{#if snapshot.preparing==='nemotron-3'}<span class="preparing">DOWNLOADING / BUILDING…</span><Button variant="outline" onclick={()=>act('CancelPreparation')}>Cancel</Button>{:else if snapshot.diarizationReady}<span class="installed">● READY</span><Button variant="ghost" disabled={active||importing||!!snapshot.preparing||settings.diarization} onclick={()=>{if(confirm==='nemotron-3'){act('RemoveModel','nemotron-3');confirm='';}else confirm='nemotron-3';}}>{confirm==='nemotron-3'?'Confirm removal?':'Remove model'}</Button>{:else}<Button disabled={active||importing||!!snapshot.preparing} onclick={()=>act('PrepareDiarization')}>Prepare Nemotron <Icon name="download"/></Button>{/if}</div><p class="footnote">First setup builds the native CUDA runtime and can take several minutes. Labels are estimates; overlapping speech can remain ambiguous.</p></section>
    <div class="section-summary"><span>{installed.length} / {snapshot.models.length} INSTALLED</span><span>{size(installed.reduce((n,m)=>n+m.bytes,0))} ON DISK</span></div><div class="model-list">{#each snapshot.models as model,i}<section class={`model-card panel ${settings.model===model.id?'chosen':''}`}><div class="model-number">0{i+1}</div><div class="model-detail"><div class="model-title"><h2>{model.name}</h2>{#if settings.model===model.id}<span class="tag acid">SELECTED</span>{/if}</div><p>{model.id==='small-q5'?'The lightweight daily driver.':model.id==='turbo-q5'?'Big-model brains. A smaller footprint.':model.id==='turbo-q8'?'Turbo, with more precision to spare.':'The heavyweight. Give every word a chance.'}</p><div class="model-meta"><span>{size(model.bytes)}</span><span>EN + DE</span><span>AUTO LANGUAGE ✓</span></div></div><div class="model-actions">{#if snapshot.preparing===model.id}<span class="preparing">PREPARING…</span>{:else if model.installed}<span class="installed">● INSTALLED</span><Button variant={settings.model===model.id?'secondary':'default'} disabled={active||importing||settings.model===model.id} onclick={()=>setting({model:model.id})}>{settings.model===model.id?'In use':'Use model'}</Button><Button variant="ghost" disabled={active||importing||!!snapshot.preparing} onclick={()=>{if(confirm===model.id){act('RemoveModel',model.id);confirm='';}else confirm=model.id;}}>{confirm===model.id?'Confirm removal?':'Remove'}</Button>{:else}<Button disabled={active||importing||!!snapshot.preparing} onclick={()=>act('PrepareModel',model.id)}><Icon name="download"/> Download</Button>{/if}</div></section>{/each}</div><p class="footnote">Downloads are verified before use. The first preparation also builds the local CUDA runtime.</p>
   {:else if page==='history'}
    <div class="section-summary"><span>{snapshot.history.length} SAVED TRANSCRIPTS</span><Button variant="ghost" disabled={!snapshot.history.length} onclick={()=>{if(confirm==='clear'){act('ClearHistory');confirm='';}else confirm='clear';}}><Icon name="trash"/>{confirm==='clear'?'Confirm clear all?':'Clear history'}</Button></div>
    {#if !snapshot.history.length}<section class="empty panel"><Icon name="history" size={56}/><h2>NOTHING ON REPEAT. YET.</h2><p>Your finished dictations will live here.<br>Copy a thought again whenever you need it.</p><Button onclick={()=>page='studio'}>Make some noise <Icon name="arrow"/></Button></section>{:else}<div class="history-list">{#each snapshot.history as entry}<article class="history-card panel"><div class="panel-top"><span>{new Date(entry.created).toLocaleString()} · {entry.seconds}s</span><span class="tag">{entry.model}</span></div><p>{entry.text}</p>{#if entry.meetingFolder}<p class="meeting-location">Audio: {entry.meetingFolder}</p>{/if}<div class="history-actions"><Button variant="outline" onclick={()=>copy(entry.text,entry.id)}><Icon name="copy"/>{copied===entry.id?'Copied':'Copy again'}</Button><Button variant="ghost" onclick={()=>{if(confirm===entry.id){act('DeleteHistory',entry.id);confirm='';}else confirm=entry.id;}}><Icon name="trash"/>{confirm===entry.id?'Confirm delete?':'Delete'}</Button></div></article>{/each}</div>{/if}
   {:else}
    <section class="settings-panel panel"><div class="setting-row"><div><h2>THE LOOK</h2><p>Same attitude. Different lighting.</p></div><div class="theme-options">{#each ['light','dark','system'] as theme}<Button variant={settings.theme===theme?'default':'outline'} aria-pressed={settings.theme===theme} onclick={()=>setting({theme})}><Icon name={theme==='light'?'sun':theme==='dark'?'moon':'system'}/>{theme}</Button>{/each}</div></div><div class="setting-row"><div><h2>RECOGNITION</h2><p>Auto detects the spoken language.</p></div><div class="setting-controls">{@render choose('model')}{@render choose('language')}</div></div><div class="setting-row"><div><h2>THE LITTLE BUBBLE</h2><p>Click it any time to switch views.</p></div><div class="theme-options"><Button variant={settings.bubbleMode==='wave'?'default':'outline'} onclick={()=>setting({bubbleMode:'wave'})}>Waveform</Button><Button variant={settings.bubbleMode==='text'?'default':'outline'} onclick={()=>setting({bubbleMode:'text'})}>Live text</Button></div></div><div class="setting-row"><div><h2>BUBBLE POSITION</h2><p>Primary display · 20 px from the edges.<br>Applied when shown, resized, or changed here.</p></div><div class="position-control"><span class="position-label">{positions.find(p=>p.id===settings.bubblePosition)?.label}</span><div class="position-grid" role="group" aria-label="Bubble position">{#each positions as position}<Button variant={settings.bubblePosition===position.id?'default':'outline'} aria-label={position.label} title={position.label} aria-pressed={settings.bubblePosition===position.id} onclick={()=>setting({bubblePosition:position.id})}><PositionIcon position={position.id}/></Button>{/each}</div></div></div><div class="setting-row"><div><h2>KEEP MY WORDS</h2><p>Save up to 200 transcripts on this device.</p></div><Switch aria-label="Save transcription history" checked={settings.saveHistory} onCheckedChange={saveHistory=>setting({saveHistory})}/></div><div class="setting-row"><div><h2>SILENCE GATE</h2><p>Skip quiet audio. Higher values may miss a soft voice.</p></div><Select.Root type="single" value={String(settings.silence)} disabled={active||importing} onValueChange={v=>{if(v)setting({silence:Number(v)});}}><Select.Trigger aria-label="Silence gate">{settings.silence===0?'Off':settings.silence===.003?'Balanced':settings.silence===.008?'Stronger':`Custom (${settings.silence})`}</Select.Trigger><Select.Content>{#each [{v:'0',name:'Off'},{v:'0.003',name:'Balanced'},{v:'0.008',name:'Stronger'}] as gate}<Select.Item value={gate.v} label={gate.name}>{gate.name}</Select.Item>{/each}</Select.Content></Select.Root></div></section>
    <HotkeySettings/>
   {/if}
   <footer><span>BUILT FOR YOUR MACHINE. NOT SOMEONE ELSE’S SERVER.</span><span>AFK ↗</span></footer>
  </main>
 </div>
{/if}
